pip install Django Step 1: Start a project with the following command django-admin startproject todo_site Step 2: Change the directory to todo_site. cd todo_site Let’s create an app now Step 3: Create an app with the following command. python manage.py startapp todo The directory structure should look like this: Step 4: Now add the todo app in your todo_site in settings.py Step 5: Edit urls.py file in todo_site Python3 from django.contrib import admin from django.urls import path from todo import views urlpatterns = [ #####################home_page########################################### path ( '' , views . index , name = "todo" ), ####################give id no. item_id name or item_id=i.id ############ # pass item_id as primary key to remove that the todo with given id path ( 'del/<str:item_id>' , views . remove , name = "del" ), ######################################################################## path ( 'admin/' , admin . site . urls ), ] Step 6: Edit models.py in todo Python3 from django.db import models from django.utils import timezone class Todo ( models . Model ): title = models . CharField ( max_length = 100 ) details = models . TextField () date = models . DateTimeField ( default = timezone . now ) def __str__ ( self ): return self . title Step 7: Edit views.py in todo Python3 from django.shortcuts import render , redirect from django.contrib import messages # import todo form and models from .forms import TodoForm from .models import Todo ############################################### def index ( request ): item_list = Todo . objects . order_by ( "-date" ) if request . method == "POST" : form = TodoForm ( request . POST ) if form . is_valid (): form . save () return redirect ( 'todo' ) form = TodoForm () page = { "forms" : form , "list" : item_list , "title" : "TODO LIST" , } return render ( request , 'todo/index.html' , page ) ### function to remove item, it receive todo item_id as primary key from url ## def remove ( request , item_id ): item = Todo . objects . get ( id = item_id ) item . delete () messages . info ( request , "item removed !!!" ) return redirect ( 'todo' ) Step 8: Now create a forms.py in todo Python3 from django import forms from .models import Todo class TodoForm ( forms . ModelForm ): class Meta : model = Todo fields = "__all__" Step 9: Register models to admin Step 10: Create templates/todo/index.html HTML <!DOCTYPE html> < html lang = "en" dir = "ltr" > < head > < meta charset = "utf-8" > < title > {{title}} </ title > < meta name = "viewport" content = "width=device-width, initial-scale=1" > < link rel = "stylesheet" href = "https://maxcdn.bootstrapcdn.com/bootstrap/3.3.7/css/bootstrap.min.css" > < script src = "https://ajax.googleapis.com/ajax/libs/jquery/3.3.1/jquery.min.js" ></ script > < script src = "https://maxcdn.bootstrapcdn.com/bootstrap/3.3.7/js/bootstrap.min.js" ></ script > <!--style--> < style > . card { box-shadow : 0 4 px 8 px 0 rgba ( 0 , 0 , 0 , 0.5 ), 0 6 px 20 px 0 rgba ( 0 , 0 , 0 , 0.39 ); background : lightpink ; margin-bottom : 5 % ; border-radius : 25 px ; padding : 2 % ; overflow : auto ; resize : both ; text-overflow : ellipsis ; } . card : hover { background : lightblue ; } . submit_form { text-align : center ; padding : 3 % ; background : pink ; border-radius : 25 px ; box-shadow : 0 4 px 8 px 0 rgba ( 0 , 0 , 0 , 0.4 ), 0 6 px 20 px 0 rgba ( 0 , 0 , 0 , 0.36 ); } </ style > </ head > < body class = "container-fluid" > {% if messages %}
